describe('Login Page Mobile View', () => {
    beforeEach(() => {
        cy.viewport('iphone-6'); // Set viewport to mobile size
        cy.visit('/login'); // Visit the login page
    });

    it('should display the login form correctly on mobile', () => {
        cy.get('h1').should('contain', 'Login'); // Check for the login heading
        cy.get('form').should('be.visible'); // Ensure the form is visible
        cy.get('input[name="username"]').should('be.visible'); // Check username input
        cy.get('input[name="password"]').should('be.visible'); // Check password input
        cy.get('button[type="submit"]').should('be.visible').and('contain', 'Submit'); // Check submit button
    });

    it('should show an error message for invalid login on mobile', () => {
        cy.get('input[name="username"]').type('invalidUser'); // Type invalid username
        cy.get('input[name="password"]').type('invalidPass'); // Type invalid password
        cy.get('button[type="submit"]').click(); // Click submit
        cy.get('.error-message').should('be.visible').and('contain', 'Invalid credentials'); // Check for error message
    });
});
